import { schema } from "@zudojs/schema";

const NewTask = schema.object({
  title: schema.string().trim().min(3).max(100),
  tags: schema.array(schema.string().max(20)).max(5),
});

function fieldErrors(issues) {
  const errors = {};
  for (const issue of issues) {
    errors[issue.path.join(".") || "(body)"] ??= issue.message;
  }
  return errors;
}

const result = NewTask.safeParse({ title: "no", tags: ["home", 42] });
console.log(fieldErrors(result.issues));

