import { schema } from "@zudojs/schema";

function isRealDate(text) {
  const [year, month, day] = text.split("-").map(Number);
  const date = new Date(Date.UTC(year, month - 1, day));
  return !Number.isNaN(date.getTime()) && date.toISOString().slice(0, 10) === text;
}

const DueDate = schema.string().max(10).refine(isRealDate, "Must be a real calendar date");
console.log(DueDate.safeParse("2026-10-01").success, DueDate.safeParse("2026-02-30").success, DueDate.safeParse("2026-13-45").success);

