import { assertDepthWithinLimit, assertSizeWithinLimit } from "@zudojs/validation";

function checkBody(body) {
  try {
    assertDepthWithinLimit(body, 10);
    assertSizeWithinLimit(body, 16384);
    return "ok";
  } catch (error) {
    return error.name === "SerializationDepthError" ? 400 : error.statusCode;
  }
}

const deep = JSON.parse("[".repeat(100) + "]".repeat(100));
